 13  -- factionfriends exitcodes:
 14  lowloyalexit  = "Keep your good work up!\nHave a nice day"
 15  midloyalexit  = "It's always a favor to see a loyal "..factionname.." Member."
 16  highloyalexit = "Very well done. We need more Veterans like you."
