 18  -- descriptions of HQ-Sections			-- first part for allied & loyal
 19  area_info_1 = "Medicare: Here you can find medicaments for all your medical needs. But beware, the stronger the drugs the bigger its sideeffects.\nOf course you can buy Medical kits as well."
 20  area_info_2 = "Personal Skill Advisor: If you don't know what is right for you, those guys can give you a hint."
 21  area_info_3 = "Faction Office: You'll find our Faction Office Assistances here. Just go and ask them what they can do for you"
 22  area_info_4 = "Main Office: You can find our personal managers in here. If something real important happens, they can provide you with info, and maybe ask for your help."
 23  area_info_5 = "Security: you can walk around here safely. The guards are well trained and protect the office against intruders."
 24  -- additional descriptions			--only viewable by loyal members
 25  area_info_6 = "Faction Supply Manager: Our faction has access to various products, which are only developed for us. This manager can hook you up with your special needs."
 26  area_info_7 = "Resource Supply Manager: As a grand service the Resource Supply Manager buys several technical items in huge batches, so he can give you faction members some credit when they buy there"
 27  
