 43  -- startmission is not defined in dialogheader (since this is no mission NPC himself)
 44  -- but it is needed since the NPC starts different missions
 45  
 46  function STARTMISSION( missionid)
 47  
 48  	if (node==state) then
 49  		SendScriptMsg("startmission", dialogclass, missionid)
 50  	end
 51  end
 52  
 53  function CANDOEPICRUN( factionid, missionid)
 54  
 55  	if (node==state) then
 56  		SendScriptMsg("candoepicrun", dialogclass, factionid, missionid)
 57  	end
 58  end
 59  
 60  -- ISFACTION(facid)
 61  
 62  function ISFACTION(facid)
 63  	if (state==node) then
 64  		CANDOEPICRUN(facid,0) ;
 65  		if (result ~= -1) then
 66  			result = 1 ;
 67  		else
 68  			result = 0 ;
 69  		end
 70  	end
 71  end
 72  
 73  -- end define
